    static bool SameKeys(const services::Settings& a,const services::Settings& b,size_t first=0){for(size_t i=first;i<a.hotkeys.size();++i)if(i!=3&&i!=4&&(a.hotkeys[i].key!=b.hotkeys[i].key||a.hotkeys[i].modifiers!=b.hotkeys[i].modifiers))return false;return true;}
